import type { PosPerformanceTableRow } from '../types/index';

export function mapComparisonLineRows(rows: PosPerformanceTableRow[]) {
  return rows.map((row) => ({
    title: row.label,
    data: (row.data ?? []).map((val) => ({
      value: val.text.replaceAll('%', ''),
      measure: val.text.includes('%') ? '%' : '',
      color: val.color,
    })),
  }));
}
